import { useCallback, useEffect, useRef, useState } from 'react';
import { useLocation } from 'react-router-dom';
import ApiService from '../services/api';
import type { NavVisibilityInput } from '../constants/appNavigation';
import { isEnterpriseAppPath } from '../constants/appNavigation';
import { getCurrentUserRole } from '../utils/authRole';
import { hasMsmeExportIntent } from '../utils/msmeExportIntent';

/**
 * Sidebar unlock state. Do NOT refetch on every pathname change — unknown URLs
 * (e.g. /This) previously re-ran this hook, failed the profile fetch, and locked
 * the whole workspace until a hard reload (CI-BUG-015).
 */
export function useNavVisibility(): NavVisibilityInput & { loading: boolean } {
  const location = useLocation();
  const enterpriseMode =
    isEnterpriseAppPath(location.pathname) || getCurrentUserRole() === 'enterprise';
  const [input, setInput] = useState<NavVisibilityInput>({
    hasProfile: false,
    hasAssessment: false,
    hasExportIntent: false,
  });
  const [loading, setLoading] = useState(true);
  const hasLoadedOnceRef = useRef(false);

  const load = useCallback(async (mode: boolean) => {
    if (!hasLoadedOnceRef.current) {
      setLoading(true);
    }
    try {
      const profileRes = mode
        ? await ApiService.getEnterpriseProfile().catch(() => null)
        : await ApiService.getMSMEProfile().catch(() => null);
      const profile = profileRes?.data;
      let hasAssessment = false;
      try {
        if (mode) {
          const workflowRes = await ApiService.getEnterpriseWorkflow().catch(() => null);
          const sections = (workflowRes?.data?.sections || []) as Array<{ status?: string }>;
          hasAssessment = sections.some((section) => section.status === 'completed')
            || Boolean((profile as { facilities?: unknown[] })?.facilities?.length);
        } else {
          const assessRes = await ApiService.request('/carbon/assessments?limit=1');
          hasAssessment = (assessRes?.data?.assessments?.length || assessRes?.data?.length || 0) > 0;
        }
      } catch {
        hasAssessment = false;
      }
      setInput({
        hasProfile: Boolean(profile?.companyName),
        hasAssessment,
        hasExportIntent: hasMsmeExportIntent(profile as Parameters<typeof hasMsmeExportIntent>[0]),
      });
      hasLoadedOnceRef.current = true;
    } catch {
      // Keep prior unlock state on transient failures so a typo URL cannot brick nav.
      setInput((prev) => (
        hasLoadedOnceRef.current
          ? prev
          : { hasProfile: false, hasAssessment: false, hasExportIntent: false }
      ));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load(enterpriseMode);
  }, [enterpriseMode, load]);

  return { ...input, loading };
}
