const EMISSION_SOURCE_BUCKETS = [
  'Fuel',
  'Transportation',
  'Electricity',
  'Water',
  'Chemicals',
  'Materials',
  'Manufacturing',
  'Waste',
  'Other',
] as const;

function getAchievementIcon(level: string): React.ReactNode {
  switch (level) {
    case 'gold':
      return <StarIcon sx={{ color: '#FFD700' }} />;
    case 'silver':
      return <StarIcon sx={{ color: '#C0C0C0' }} />;
    case 'bronze':
      return <StarIcon sx={{ color: '#CD7F32' }} />;
    default:
      return <CheckCircleIcon color="primary" />;
  }
}

type EmissionSourceBucket = (typeof EMISSION_SOURCE_BUCKETS)[number];

function mapLabelToEmissionSourceBucket(raw: string): EmissionSourceBucket {
  const s = raw.toLowerCase().replace(/_/g, ' ');
  if (/\b(fuel|diesel|petrol|gasoline|lpg|cng|lng|furnace oil|hfo|combustion)\b/.test(s)) return 'Fuel';
  if (/\b(transport|vehicle|fleet|logistics|freight|delivery|shipping|commute|travel|mobility)\b/.test(s)) {
    return 'Transportation';
  }
  if (/\b(electric|grid|power|utility|kwh|mwh|energy bill|scope\s*2)\b/.test(s)) return 'Electricity';
  if (/water|wastewater|effluent|sewage/.test(s)) return 'Water';
  if (/chemical|solvent|paint|acid|alkali|adhesive|reagent|hazardous/.test(s)) return 'Chemicals';
  if (/raw material|materials|procurement|supplier|purchase|inventory|inputs|packaging/.test(s)) return 'Materials';
  if (/manufactur|process line|machinery|production|fabrication/.test(s)) return 'Manufacturing';
  if (/waste|landfill|incineration|scrap|recycl/.test(s)) return 'Waste';
  return 'Other';
}

function aggregateEmissionSourcesFromKgRows(rows: { label: string; kg: number }[]) {
  const acc = new Map<EmissionSourceBucket, number>();
  EMISSION_SOURCE_BUCKETS.forEach((b) => acc.set(b, 0));
  rows.forEach(({ label, kg }) => {
    const b = mapLabelToEmissionSourceBucket(label);
    acc.set(b, (acc.get(b) || 0) + Math.max(0, kg));
  });
  return EMISSION_SOURCE_BUCKETS.map((name) => ({
    name,
    kg: acc.get(name) || 0,
    tCO2e: (acc.get(name) || 0) / 1000,
  })).filter((r) => r.kg > 0);
}

function flattenEsgBreakdownToRows(esg: CarbonStatsPayload['esgScopes']): { label: string; kg: number }[] {
  if (!esg) return [];
  const rows: { label: string; kg: number }[] = [];
  const push = (scopeTag: string, breakdown: Record<string, number> | undefined) => {
    if (!breakdown || typeof breakdown !== 'object') return;
    Object.entries(breakdown).forEach(([key, val]) => {
      const kg = typeof val === 'number' && !Number.isNaN(val) ? val : 0;
      if (kg > 0) rows.push({ label: `${scopeTag} ${key.replace(/_/g, ' ')}`, kg });
    });
  };
  push('Scope 1', esg.scope1?.breakdown as Record<string, number> | undefined);
  push('Scope 2', esg.scope2?.breakdown as Record<string, number> | undefined);
  push('Scope 3', esg.scope3?.breakdown as Record<string, number> | undefined);
  return rows;
}

function getHotspotCopy(carbon: CarbonStatsPayload | undefined): string {
  const cat = carbon?.categoryBreakdown;
  if (cat && typeof cat === 'object') {
    const entries = Object.entries(cat)
      .map(([name, v]) => ({
        name,
        co2: Number((v as { co2Emissions?: number; co2?: number })?.co2Emissions ?? (v as { co2?: number })?.co2 ?? 0) || 0,
      }))
      .filter((e) => e.co2 > 0)
      .sort((a, b) => b.co2 - a.co2);
    if (entries.length > 0) {
      const labels = entries.slice(0, 3).map((e) => e.name.replace(/_/g, ' '));
      return `Highest-impact categories in this assessment: ${labels.join(', ')}.`;
    }
  }
  const esg = carbon?.esgScopes;
  if (!esg) return 'Complete a carbon assessment to see category hotspots.';
  const parts: { label: string; value: number }[] = [];
  const addBreak = (obj: Record<string, number> | undefined, prefix: string) => {
    if (!obj || typeof obj !== 'object') return;
    Object.entries(obj).forEach(([key, val]) => {
      if (typeof val === 'number' && val > 0) {
        const words = key.replace(/([A-Z])/g, ' $1').trim();
        parts.push({ label: `${prefix} — ${words}`, value: val });
      }
    });
  };
  addBreak(esg.scope1?.breakdown as Record<string, number> | undefined, 'Scope 1');
  addBreak(esg.scope2?.breakdown as Record<string, number> | undefined, 'Scope 2');
  addBreak(esg.scope3?.breakdown as Record<string, number> | undefined, 'Scope 3');
  if (parts.length === 0) {
    return 'Assessment data will highlight your highest-impact categories here.';
  }
  parts.sort((a, b) => b.value - a.value);
  const top = parts.slice(0, 3).map((p) => p.label);
  return `${top.join('; ')} — among the largest contributors in this assessment.`;
}

const Dashboard: React.FC = () => {
  useOrchestrationEvents(true);
  const { t } = useAppTranslation();
  const { locale } = useReadinessLocale();
  const dashboardUi = DASHBOARD_MSME_LOCALE[locale];
  const navigate = useNavigate();
  const [advancedOpen, setAdvancedOpen] = useState(false);

  const profileQuery = useMsmeProfileQuery();
  const statsQuery = useMsmeStatsQuery();
  const savingsQuery = useCarbonSavingsQuery();
  const carbonDashboardQuery = useCarbonDashboardQuery();
  // Finance overview is light and powers the top NBA — keep it on mount.
  const financeOverviewQuery = useFinanceOverviewQuery();
  // Heavy advisory / peer / target panels load only when "More insights" is opened.
  const reductionTargetQuery = useReductionTargetQuery(advancedOpen);
  const peerBenchmarkQuery = useIndustryPeerBenchmarkQuery(
    advancedOpen && !profileQuery.isLoading && Boolean(profileQuery.data)
  );
  const advisoryQuery = useMsmeAdvisoryQuery(
    advancedOpen && !profileQuery.isLoading && Boolean(profileQuery.data)
  );

  const setupProgress = useMsmeSetupProgress(true);

  const dashboardBundle = useMemo(
    () =>
      buildDashboardBundle({
        profileResponse: profileQuery.data,
        statsResponse: statsQuery.data,
        savingsResponse: savingsQuery.data,
        dashboardResponse: carbonDashboardQuery.data,
      }),
    [profileQuery.data, statsQuery.data, savingsQuery.data, carbonDashboardQuery.data]
  );

  const {
    msmeData,
    statsData,
    carbonSavings,
    additionalSavingsMetrics,
    documentCarbonSummary,
  } = dashboardBundle;

  const isLoading =
    profileQuery.isLoading
    || statsQuery.isLoading
    || savingsQuery.isLoading
    || carbonDashboardQuery.isLoading;

  const dashboardQueryError = useMemo(() => {
    const candidates = [
      profileQuery.error,
      statsQuery.error,
      carbonDashboardQuery.error,
    ];
    const first = candidates.find((err) => err instanceof Error);
    return first instanceof Error ? first.message : null;
  }, [profileQuery.error, statsQuery.error, carbonDashboardQuery.error]);

  const financeOverviewLoading = financeOverviewQuery.isLoading;
  const financeOverview = useMemo(() => {
    const payload = (financeOverviewQuery.data as {
      data?: { summary?: { eligibleCount?: number; inProgressCount?: number; headline?: string } };
    } | undefined)?.data;
    if (!payload?.summary) {
      return null;
    }
    return {
      eligibleCount: Number(payload.summary.eligibleCount ?? 0),
      inProgressCount: Number(payload.summary.inProgressCount ?? 0),
      headline: payload.summary.headline || '',
    };
  }, [financeOverviewQuery.data]);

  const resolvedCarbonFields = useMemo(
    () => resolveDashboardCarbonFields(statsData?.carbon as CarbonStatsPayload | undefined),
    [statsData]
  );

  const carbonApi = statsData?.carbon as CarbonStatsPayload | undefined;
  const carbonScore = Number(statsData?.carbon?.currentScore || 0);
  const rawCarbonEmissionsKg = Number(statsData?.carbon?.totalCO2Emissions || 0);
  const esg = resolvedCarbonFields.esgScopes || carbonApi?.esgScopes;
  const s1Kg = Number(esg?.scope1?.total) || 0;
  const s2Kg = Number(esg?.scope2?.total) || 0;
  const s3Kg = Number(esg?.scope3?.total) || 0;
  const scopeSumKg = s1Kg + s2Kg + s3Kg;
  // CI-BUG-001: keep hero total aligned with scope bars when assessment total diverges.
  const carbonEmissionsKg = reconcileHeroCarbonTotalKg(rawCarbonEmissionsKg, scopeSumKg);
  const predictions = carbonApi?.predictions;
  const forecastKgFromModel =
    predictions && predictions.length > 0
      ? predictions.reduce((sum, p) => sum + (Number(p.predictedCO2) || 0), 0)
      : null;
  const forecastTCO2e =
    forecastKgFromModel != null && forecastKgFromModel > 0
      ? forecastKgFromModel / 1000
      : carbonEmissionsKg > 0
        ? (carbonEmissionsKg * 1.08) / 1000
        : 0;
  const forecastCaption =
    forecastKgFromModel != null && forecastKgFromModel > 0
      ? 'Sum of modelled periods from your latest assessment'
      : carbonEmissionsKg > 0
        ? 'Estimated from current assessment footprint (+8% run-rate)'
        : 'Complete an assessment to see a forecast';
  const hotspotDescription = getHotspotCopy({
    ...carbonApi,
    categoryBreakdown: resolvedCarbonFields.categoryBreakdown || carbonApi?.categoryBreakdown,
    esgScopes: esg,
  });
  const lastAssessmentLabel = carbonApi?.lastAssessment
    ? new Date(carbonApi.lastAssessment).toLocaleString()
    : null;
  const assessmentPeriodLabel =
    carbonApi?.assessmentPeriod?.startDate && carbonApi?.assessmentPeriod?.endDate
      ? `${new Date(carbonApi.assessmentPeriod.startDate).toLocaleDateString()} – ${new Date(
          carbonApi.assessmentPeriod.endDate
        ).toLocaleDateString()}`
      : null;

  const getCarbonScoreColor = (score: number): string => {
    if (score >= 80) return 'success';
    if (score >= 50) return 'warning';
    return 'error';
  };

  const getCarbonScoreLabel = (score: number): string => {
    if (score >= 80) return 'Excellent';
    if (score >= 60) return 'Good';
    if (score >= 40) return 'Average';
    return 'Needs Improvement';
  };

  const getPerformanceLabel = (performance?: string): string => {
    switch (String(performance || '').toLowerCase()) {
      case 'excellent':
        return 'Excellent';
      case 'good':
        return 'Good';
      case 'average':
        return 'Average';
      case 'below_average':
        return 'Below Average';
      case 'poor':
        return 'Needs Improvement';
      case '':
      case 'undefined':
      case 'null':
        return 'Not Assessed';
      default:
        return performance || 'Not Assessed';
    }
  };

  /** Prefer API benchmark performance over score-band when they disagree (CI-BUG-003). */
  const resolveHeroScoreLabel = (score: number, performance?: string): string => {
    const normalized = String(performance || '').toLowerCase();
    if (normalized === 'poor' || normalized === 'below_average') {
      return getPerformanceLabel(performance);
    }
    if (normalized === 'excellent' || normalized === 'good' || normalized === 'average') {
      return getPerformanceLabel(performance);
    }
    return getCarbonScoreLabel(score);
  };

  const isOnTrackStatus = (score: number, performance?: string): boolean => {
    const normalized = String(performance || '').toLowerCase();
    if (normalized === 'poor' || normalized === 'below_average') return false;
    if (normalized === 'excellent' || normalized === 'good') return true;
    return score >= 70;
  };

  const carbonDashboardPayload = useMemo(() => {
    const record = carbonDashboardQuery.data as Record<string, unknown> | null | undefined;
    if (!record || typeof record !== 'object') return null;
    const nested = record.data;
    return (nested && typeof nested === 'object' ? nested : record) as Record<string, unknown>;
  }, [carbonDashboardQuery.data]);

  const dashboardRecommendations = useMemo(() => {
    const fromDashboard = carbonDashboardPayload?.topRecommendations;
    const fromStats = statsData?.topRecommendations;
    const raw = Array.isArray(fromDashboard) && fromDashboard.length > 0
      ? fromDashboard
      : (Array.isArray(fromStats) ? fromStats : []);
    return raw.map((rec, index) => {
      const item = rec as Record<string, unknown>;
      return {
        id: String(item.id || `rec-${index + 1}`),
        title: String(item.title || 'Recommendation'),
        description: item.description ? String(item.description) : undefined,
        priority: item.priority ? String(item.priority) : undefined,
        category: item.category ? String(item.category) : undefined,
        potentialCO2Reduction: item.potentialCO2Reduction != null
          ? Number(item.potentialCO2Reduction)
          : undefined,
        isImplemented: Boolean(item.isImplemented),
        status: item.status ? String(item.status) : undefined,
        mitigationActions: Array.isArray(item.mitigationActions) ? item.mitigationActions : [],
        selectedActions: Array.isArray(item.selectedActions) ? item.selectedActions : [],
      } satisfies MitigationRecommendation;
    });
  }, [carbonDashboardPayload, statsData?.topRecommendations]);

  const latestAssessmentId = useMemo(() => {
    const id = carbonDashboardPayload?.latestAssessmentId;
    return typeof id === 'string' && id.length > 0 ? id : null;
  }, [carbonDashboardPayload]);

  useEffect(() => {
    const pct = Number(
      (reductionTargetQuery.data as { data?: { reductionTargetPct?: number } } | undefined)?.data
        ?.reductionTargetPct
    );
    if (!Number.isFinite(pct)) {
      return;
    }
    window.localStorage.setItem('sustainow_emissions_reduction_target_pct_v1', String(pct));
  }, [reductionTargetQuery.data]);

  useEffect(() => {
    void acceptPendingSupplierInviteIfAny();
  }, []);

  const emissionSourceBarData = useMemo(() => {
    const carbon = {
      ...(statsData?.carbon as CarbonStatsPayload | undefined),
      categoryBreakdown: resolvedCarbonFields.categoryBreakdown || undefined,
      esgScopes: resolvedCarbonFields.esgScopes || (statsData?.carbon as CarbonStatsPayload | undefined)?.esgScopes,
    };
    const cat = carbon?.categoryBreakdown;
    if (cat && typeof cat === 'object' && Object.keys(cat).length > 0) {
      const rows = Object.entries(cat).map(([name, v]) => {
        const raw = (v as { co2Emissions?: number; co2?: number })?.co2Emissions ?? (v as { co2?: number })?.co2 ?? 0;
        const kg = Number(raw) || 0;
        return { label: name.replace(/_/g, ' '), kg };
      });
      const aggregated = aggregateEmissionSourcesFromKgRows(rows);
      if (aggregated.length > 0) return aggregated;
    }
    return aggregateEmissionSourcesFromKgRows(flattenEsgBreakdownToRows(carbon?.esgScopes));
  }, [statsData, resolvedCarbonFields]);

  const measurementCompleteness = useMemo(() => {
    const energy = inferEnergySignals({
      categoryBreakdown: emissionSourceBarData.map((row) => ({ name: row.name, kg: row.kg })),
      scope1Kg: s1Kg,
      scope2Kg: s2Kg,
    });
    const documentCountLocal = Number(statsData?.documentBulkUpload?.totalDocuments ?? 0);
    const hasDocumentsLocal =
      documentCountLocal > 0
      || Boolean(documentCarbonSummary?.totals)
      || Number(statsData?.documentBulkUpload?.totalTransactions ?? 0) > 0;
    const hasAssessmentLocal = carbonEmissionsKg > 0 || carbonScore > 0;
    return deriveMeasurementCompleteness({
      hasProfile: Boolean(msmeData?.companyName && msmeData?.gstNumber),
      hasDocuments: hasDocumentsLocal,
      hasAssessment: hasAssessmentLocal,
      hasWorkflow: hasAssessmentLocal,
      hasElectricitySignal: energy.hasElectricitySignal,
      hasFuelSignal: energy.hasFuelSignal,
    });
  }, [
    emissionSourceBarData,
    s1Kg,
    s2Kg,
    msmeData?.companyName,
    msmeData?.gstNumber,
    statsData,
    documentCarbonSummary,
    carbonEmissionsKg,
    carbonScore,
  ]);

  if (isLoading) {
    return (
      <Box
        sx={{
          py: { xs: 6, md: 8 },
          px: 2,
          maxWidth: 520,
          mx: 'auto',
          textAlign: 'center',
        }}
      >
        <CircularProgress size={44} thickness={4} sx={{ mb: 2.5, color: 'primary.main' }} />
        <Typography variant="h6" sx={{ fontWeight: 700, mb: 0.75, letterSpacing: '-0.02em' }}>
          Preparing your workspace
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 3, lineHeight: 1.6 }}>
          Pulling your company profile, transactions, and emissions signals into one view.
        </Typography>
        <LinearProgress sx={{ height: 6, borderRadius: 3, maxWidth: 400, mx: 'auto' }} />
      </Box>
    );
  }

  if (dashboardQueryError) {
    return (
      <Alert
        severity="error"
        sx={{ mt: 2 }}
        action={(
          <Button
            color="inherit"
            size="small"
            onClick={() => {
              void profileQuery.refetch();
              void statsQuery.refetch();
              void carbonDashboardQuery.refetch();
            }}
          >
            Retry
          </Button>
        )}
      >
        {dashboardQueryError}
      </Alert>
    );
  }

  if (!msmeData) {
    return (
      <Alert severity="info" sx={{ mt: 2 }}>
        No MSME registration found. Please complete the registration first.
        <Button variant="contained" sx={{ ml: 2 }} onClick={() => navigate('/msme-registration')}>
          Register Now
        </Button>
      </Alert>
    );
  }

  const scoreColor = getCarbonScoreColor(carbonScore) as 'success' | 'warning' | 'error';

  const totalCo2SavedKg = Number(
    additionalSavingsMetrics?.totalCO2Saved ?? carbonSavings?.totalSavings ?? 0
  );
  const periodCo2SavedKg = Number(carbonSavings?.periodSavings ?? 0);
  const savingsPercentage = Number(carbonSavings?.savingsPercentage ?? 0);
  const costSavingsInr = Number(
    additionalSavingsMetrics?.costSavings ?? totalCo2SavedKg * 0.05
  );
  const treesEquivalent = Number(
    additionalSavingsMetrics?.environmentalImpact?.treesEquivalent ??
      (totalCo2SavedKg > 0 ? Math.round(totalCo2SavedKg / 22) : 0)
  );
  const greenCreditsAvailable = Number(statsData?.carbonCredits?.availableCredits ?? 0);
  const assessmentCount = Number(
    statsData?.carbon?.totalAssessments
    ?? statsData?.carbon?.assessmentCount
    ?? statsData?.assessments?.total
    ?? 0
  );
  const benchmarkPerformance = getPerformanceLabel(carbonSavings?.benchmarkComparison?.performance);

  const transactionCount = Number(statsData?.transactions?.total ?? 0);
  const documentCount = Number(statsData?.documentBulkUpload?.totalDocuments ?? 0);
  const hasAssessment = carbonEmissionsKg > 0 || carbonScore > 0;
  const hasProfile = Boolean(msmeData?.companyName && msmeData?.gstNumber);
  const hasDocuments =
    documentCount > 0 ||
    Boolean(documentCarbonSummary?.totals) ||
    Number(statsData?.documentBulkUpload?.totalTransactions ?? 0) > 0;

  const dataQuality = computeDataQualityScore({
    hasProfile,
    hasAssessment,
    carbonEmissionsKg,
    transactionCount,
    documentCount,
    hasScopeBreakdown: scopeSumKg > 0,
  });

  const advisoryPayload: MsmeAdvisoryPayload | null =
    (advisoryQuery.data as { data?: MsmeAdvisoryPayload } | undefined)?.data ?? null;

  const advisoryError = advisoryQuery.error instanceof Error
    ? advisoryQuery.error.message
    : advisoryQuery.error
      ? 'AI advisory unavailable'
      : null;

  const frameworkGaps = deriveFrameworkDataGaps({
    hasProfile,
    hasAssessment,
    carbonEmissionsKg,
    transactionCount,
    documentCount,
    hasScopeBreakdown: scopeSumKg > 0,
  });

  const prioritizedAdvisoryAction =
    advisoryPayload?.nextBestAction
    ?? advisoryPayload?.outputs?.goalAdvisory?.prioritizedActions?.[0]
    ?? null;

  const baseNextBestAction = deriveNextBestAction({
    hasProfile,
    hasDocuments,
    hasAssessment,
    hasReportGoal: setupProgress.hasReportGoal,
    carbonScore,
  });

  const nextBestAction = deriveNextBestActionFromAdvisory(
    baseNextBestAction,
    prioritizedAdvisoryAction
  );

  const financeNextBestAction = deriveFinanceNextBestAction({
    hasAssessment,
    eligibleCount: financeOverview?.eligibleCount ?? 0,
    inProgressCount: financeOverview?.inProgressCount ?? 0,
  });

  const signupGoal = typeof window !== 'undefined' ? getStoredSignupGoal() : null;

  const showFinanceNba =
    setupProgress.hasReportGoal
    && hasAssessment
    && financeNextBestAction
    && (
      (financeOverview?.eligibleCount ?? 0) > 0
      || (financeOverview?.inProgressCount ?? 0) > 0
      || signupGoal === 'green_finance'
      || setupProgress.progress.allComplete
    );

  const hasWorkflowComplete = true;

  const setupInProgress = !setupProgress.loading && !setupProgress.progress.allComplete;

  const achievements = carbonSavings?.achievements ?? [];
  const milestones = carbonSavings?.nextMilestones ?? [];
  const showProgressCards = achievements.length > 0 || milestones.length > 0;

  const advancedDashboardPanels = (
    <>
      {!setupInProgress ? (
        <Box component="section" aria-label="Sustainability snapshot" sx={{ mb: 3 }}>
          <DashboardMetricsGrid
            carbonScore={carbonScore}
            scoreLabel={resolveHeroScoreLabel(carbonScore, carbonSavings?.benchmarkComparison?.performance)}
            scoreColor={scoreColor}
            carbonEmissionsKg={carbonEmissionsKg}
            totalCo2SavedKg={totalCo2SavedKg}
            periodCo2SavedKg={periodCo2SavedKg}
            savingsPercentage={savingsPercentage}
            costSavingsInr={costSavingsInr}
            treesEquivalent={treesEquivalent}
            greenCreditsAvailable={greenCreditsAvailable}
            forecastTCO2e={forecastTCO2e}
          />
        </Box>
      ) : null}

      <MeasurementCompletenessRing
        completeness={measurementCompleteness}
        title="How complete is your carbon measurement?"
      />

      <DashboardOperationsPrompt
        visible={
          hasDocuments
          && measurementCompleteness.dimensions.some(
            (dim) => (dim.id === 'electricity' || dim.id === 'fuel') && !dim.complete
          )
        }
      />

      {!setupInProgress && showProgressCards ? (
        <Box component="section" aria-label="Achievements and milestones" sx={{ mb: 3 }}>
          <DashboardProgressCards
            achievements={achievements}
            milestones={milestones}
            getAchievementIcon={getAchievementIcon}
          />
        </Box>
      ) : null}

      <DashboardMsmeAdvisoryPanel
        advisory={advisoryPayload}
        loading={advisoryQuery.isLoading}
        error={advisoryError}
      />

      <DashboardFrameworkGapsCard gaps={frameworkGaps} />

      <DashboardIsoReadinessCard />

      <Box component="section" aria-label="Industry peer benchmark" sx={{ mb: 3 }}>
        <IndustryPeerBenchmarkDashboard
          data={peerBenchmarkQuery.data}
          loading={peerBenchmarkQuery.isLoading}
        />
      </Box>

      <DashboardRecommendationsCard
        recommendations={dashboardRecommendations}
        latestAssessmentId={latestAssessmentId}
      />

      <DashboardCarbonOffsetsCard
        greenCreditsAvailable={greenCreditsAvailable}
        carbonEmissionsKg={carbonEmissionsKg}
      />

      <DashboardFinanceCard
        loading={financeOverviewLoading}
        eligibleCount={financeOverview?.eligibleCount ?? 0}
        inProgressCount={financeOverview?.inProgressCount ?? 0}
        headline={financeOverview?.headline}
      />

      {carbonSavings ? (
        <Box sx={{ mb: 3, display: 'flex', justifyContent: 'flex-end' }}>
          <Button variant="outlined" size="small" onClick={() => navigate('/carbon-savings')}>
            {t('dashboard.viewCarbonSavings')}
          </Button>
        </Box>
      ) : null}
    </>
  );

  return (
    <Box>
      <Box sx={{ mb: 3, display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 2, flexWrap: 'wrap' }}>
        <Box>
          <Typography variant="h5" sx={{ fontWeight: 700, letterSpacing: '-0.02em', mb: 0.5 }}>
            Welcome back, {msmeData.companyName}
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 720, lineHeight: 1.6 }}>
            {dashboardUi.welcomeSubtitle}
          </Typography>
        </Box>
      </Box>

      <Box component="section" aria-label={dashboardUi.gettingStartedLabel} sx={{ mb: 3 }}>
        {/* DEEP-BUG-008: only one onboarding model on Dashboard — checklist owns steps. */}
        {setupProgress.loading || setupProgress.progress.allComplete ? (
          <MsmeWorkflowGuidePanel />
        ) : null}
        <ScopeExplainerStrip
          scope1Kg={s1Kg}
          scope2Kg={s2Kg}
          scope3Kg={s3Kg}
          compact
        />
      </Box>

      <Box component="section" aria-label="Performance" sx={{ mb: 3 }}>
        <DashboardHero
          carbonScore={carbonScore}
          scoreLabel={resolveHeroScoreLabel(carbonScore, carbonSavings?.benchmarkComparison?.performance)}
          onTrack={isOnTrackStatus(carbonScore, carbonSavings?.benchmarkComparison?.performance)}
          scoreColor={scoreColor}
          carbonEmissionsKg={carbonEmissionsKg}
          s1Kg={s1Kg}
          s2Kg={s2Kg}
          s3Kg={s3Kg}
          scopeSumKg={scopeSumKg}
          lastAssessmentLabel={lastAssessmentLabel}
          assessmentPeriodLabel={assessmentPeriodLabel}
          forecastTCO2e={forecastTCO2e}
          forecastCaption={forecastCaption}
          hotspotDescription={hotspotDescription}
          dataQuality={{
            level: dataQuality.level,
            label: dataQuality.label,
            score: dataQuality.score,
            hints: dataQuality.hints,
          }}
          msmeHighlights={{
            transactionCount,
            documentCount,
            assessmentCount,
            greenCreditsAvailable,
            totalCo2SavedKg,
            periodCo2SavedKg,
            savingsPercentage,
            costSavingsInr,
            treesEquivalent,
            benchmarkPerformance,
            companyType: msmeData.companyType,
            industry: msmeData.industry,
            employeeCount: msmeData.business?.numberOfEmployees,
          }}
        />
      </Box>

      <Box component="section" aria-label="To-do actions" sx={{ mb: 3 }}>
        <DashboardSectionHeading
          title="What to do next"
          subtitle="One clear next step — then use the quick actions below."
        />
        {!setupProgress.loading && !setupProgress.progress.allComplete ? (
          <DashboardOnboardingChecklist progress={setupProgress.progress} />
        ) : showFinanceNba && financeNextBestAction ? (
          <DashboardNextBestAction action={financeNextBestAction} />
        ) : (
          <DashboardNextBestAction action={nextBestAction} />
        )}

        <Box sx={{ mt: 2 }}>
          <DashboardQuickActions
            hasAssessment={hasAssessment}
            hasDocuments={hasDocuments}
            hasWorkflow={hasWorkflowComplete}
          />
        </Box>
      </Box>

      <DashboardSetupFocusSection
        defaultExpanded={false}
        expanded={advancedOpen}
        onExpandedChange={setAdvancedOpen}
      >
        {advancedDashboardPanels}
      </DashboardSetupFocusSection>
    </Box>
  );
};

export default Dashboard;
